      "keystrokes": "python3 - <<'PY'\nimport struct\nb=open('doomgeneric_mips','rb').read(64)\nprint('first bytes', b[:16])\nprint('magic', b[:4])\nprint('class', b[4], 'data', b[5], 'version', b[6], 'osabi', b[7])\nprint('type', struct.unpack('<H',b[16:18])[0], 'machine', struct.unpack('<H',b[18:20])[0])\nprint('entry', struct.unpack('<I',b[24:28])[0] if b[4]==1 else struct.unpack('<Q',b[24:32])[0])\nprint('phoff', struct.unpack('<I',b[28:32])[0], 'shoff', struct.unpack('<I',b[32:36])[0])\nprint('flags', struct.unpack('<I',b[36:40])[0])\nprint('ehsize', struct.unpack('<H',b[40:42])[0], 'phentsize', struct.unpack('<H',b[42:44])[0], 'phnum', struct.unpack('<H',b[44:46])[0])\nPY\n",
